const tok = input.trim().split(/\s+/);
let pos = 0;
const nextInt = () => parseInt(tok[pos++], 10);
const r = nextInt(), c = nextInt();
const flat = [];
for (let k = 0; k < r * c; k++) flat.push(nextInt());
let nr = nextInt(), nc = nextInt();
if (r * c !== nr * nc) { nr = r; nc = c; }
const out = [];
for (let i = 0; i < nr; i++) out.push(flat.slice(i * nc, (i + 1) * nc).join(" "));
console.log(out.join("\n"));
